// Hand-rolled, when the index semantics need to be explicit.
func search(a []int, target int) int {
	lo, hi := 0, len(a)-1
	for lo <= hi {
		mid := lo + (hi-lo)/2 // avoids the overflow (lo+hi)/2 can hit
		switch {
		case a[mid] == target:
			return mid
		case a[mid] < target:
			lo = mid + 1
		default:
			hi = mid - 1
		}
	}
	return -1
}

// Binary search on the answer: smallest value for which feasible is true.
func minFeasible(lo, hi int, feasible func(int) bool) int {
	for lo < hi {
		mid := lo + (hi-lo)/2
		if feasible(mid) {
			hi = mid // keep mid as a candidate
		} else {
			lo = mid + 1
		}
	}
	return lo
}

