// Go grows goroutine stacks dynamically, so deep recursion is far safer here
// than in Python or C — but it is still not free.
func fib(n int, memo map[int]int) int {
	if n <= 1 {
		return n
	}
	if v, ok := memo[n]; ok {
		return v
	}
	memo[n] = fib(n-1, memo) + fib(n-2, memo)
	return memo[n]
}

// Subsets: at each index, take the element or don't.
func subsets(nums []int) [][]int {
	var out [][]int
	var cur []int

	var go_ func(i int)
	go_ = func(i int) {
		if i == len(nums) {
			// MUST copy: cur's backing array is reused as we backtrack.
			out = append(out, append([]int(nil), cur...))
			return
		}
		go_(i + 1) // skip
		cur = append(cur, nums[i])
		go_(i + 1) // take
		cur = cur[:len(cur)-1]
	}
	go_(0)
	return out
}

void backtrack(State& s, vector<Solution>& out) {
    if (isGoal(s)) { out.push_back(extract(s)); return; }
    for (auto& choice : choices(s)) {
        apply(s, choice);        // try
        backtrack(s, out);       // recurse
        undo(s, choice);         // un-try
    }
}

bool safe(vector<int>& col, int r, int c) {
    for (int i = 0; i < r; i++)
        if (col[i] == c || abs(col[i]-c) == abs(i-r)) return false;
    return true;
}
void solve(int r, int n, vector<int>& col, int& count) {
    if (r == n) { count++; return; }
    for (int c = 0; c < n; c++)
        if (safe(col, r, c)) {
            col[r] = c;          // place
            solve(r+1, n, col, count);
            col[r] = -1;         // remove (backtrack)
        }
}

// choose -> explore -> un-choose. The un-choose is what makes it
// backtracking rather than plain recursion.
static void permute(int[] nums, boolean[] used, List<Integer> cur, List<List<Integer>> out) {
    if (cur.size() == nums.length) { out.add(new ArrayList<>(cur)); return; }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) continue;
        used[i] = true; cur.add(nums[i]);        // choose
        permute(nums, used, cur, out);           // explore
        cur.remove(cur.size() - 1); used[i] = false; // un-choose
    }
}

