# Reverse: rewire each next pointer backwards as you walk forward.
def reverse(head: ListNode | None) -> ListNode | None:
    prev = None
    while head:
        head.next, prev, head = prev, head, head.next   # save-rewire-advance
    return prev

# Floyd: slow moves 1, fast moves 2. Meeting means a cycle. Reset one pointer
# to head, advance both by 1, and they meet at the cycle entry.
def cycle_start(head: ListNode | None) -> ListNode | None:
    slow = fast = head
    while fast and fast.next:
        slow, fast = slow.next, fast.next.next
        if slow is fast:
            slow = head
            while slow is not fast:
                slow, fast = slow.next, fast.next
            return slow
    return None

# Middle of the list — the same fast/slow idea.
def middle(head: ListNode | None) -> ListNode | None:
    slow = fast = head
    while fast and fast.next:
        slow, fast = slow.next, fast.next.next
    return slow

