// Floyd: slow moves 1, fast moves 2. Meeting means a cycle; reset one to head
// and step both by 1 to land on the cycle entry.
func cycleStart(head *ListNode) *ListNode {
	slow, fast := head, head
	for fast != nil && fast.Next != nil {
		slow, fast = slow.Next, fast.Next.Next
		if slow == fast {
