def next_greater(a: list[int]) -> list[int]:
    res = [-1] * len(a)
    stack: list[int] = []              # indices, values decreasing
    for i, x in enumerate(a):
        while stack and a[stack[-1]] < x:
            res[stack.pop()] = x
        stack.append(i)
    return res

# Sliding window maximum with a deque. Use deque, not list — list.pop(0) is O(n).
from collections import deque

def window_max(a: list[int], k: int) -> list[int]:
    dq: deque[int] = deque()           # indices
    out: list[int] = []
    for i, x in enumerate(a):
        while dq and dq[0] <= i - k:
            dq.popleft()               # fell out of the window
        while dq and a[dq[-1]] <= x:
            dq.pop()                   # dominated by x, can never be the max
        dq.append(i)
        if i >= k - 1:
            out.append(a[dq[0]])
    return out

/* A stack is an array plus a top index. */
typedef struct { int *data; int top, cap; } Stack;

void st_push(Stack *s, int x) { s->data[++s->top] = x; }
int  st_pop(Stack *s)         { return s->data[s->top--]; }
int  st_peek(const Stack *s)  { return s->data[s->top]; }
int  st_empty(const Stack *s) { return s->top < 0; }   /* init top = -1 */

/* A queue needs head and tail. Wrap them modulo cap (a circular buffer),
   otherwise the array is exhausted after cap total pushes even if empty. */
typedef struct { int *data; int head, tail, count, cap; } Queue;

void q_push(Queue *q, int x) {
    q->data[q->tail] = x;
    q->tail = (q->tail + 1) % q->cap;
    q->count++;
}

int q_pop(Queue *q) {
    int x = q->data[q->head];
    q->head = (q->head + 1) % q->cap;
    q->count--;
    return x;
}

/* Monotonic stack — next greater element. Each index is pushed and popped
   at most once, so O(n). */
void nextGreater(const int *a, int n, int *res) {
    int *st = malloc((size_t) n * sizeof *st);
    int top = -1;
    for (int i = 0; i < n; i++) res[i] = -1;
    for (int i = 0; i < n; i++) {
        while (top >= 0 && a[st[top]] < a[i]) res[st[top--]] = a[i];
        st[++top] = i;
    }
    free(st);
}

// The pattern behind next-greater, largest-rectangle and daily-temperatures.
// Each index is pushed and popped at most once, so O(n) overall.
func nextGreater(a []int) []int {
	res := make([]int, len(a))
	for i := range res {
		res[i] = -1
	}
	var stack []int // indices, values decreasing
	for i, x := range a {
		for len(stack) > 0 && a[stack[len(stack)-1]] < x {
			res[stack[len(stack)-1]] = x
			stack = stack[:len(stack)-1]
		}
		stack = append(stack, i)
	}
	return res
}

// Sliding window maximum with a deque of indices.
func windowMax(a []int, k int) []int {
	var dq []int // indices; a[dq] decreasing
	var out []int
	for i, x := range a {
		for len(dq) > 0 && dq[0] <= i-k {
			dq = dq[1:] // left the window
		}
		for len(dq) > 0 && a[dq[len(dq)-1]] <= x {
			dq = dq[:len(dq)-1] // dominated, can never be the max
		}
		dq = append(dq, i)
		if i >= k-1 {
			out = append(out, a[dq[0]])
		}
	}
	return out
}

struct TreeNode {
    int val; TreeNode *left, *right;
    TreeNode(int x): val(x), left(nullptr), right(nullptr) {}
};
void inorder(TreeNode* root, vector<int>& out) {
    if (!root) return;
    inorder(root->left, out);
    out.push_back(root->val);
    inorder(root->right, out);
}

vector<vector<int>> levelOrder(TreeNode* root) {
    vector<vector<int>> res;
    if (!root) return res;
    queue<TreeNode*> q; q.push(root);
    while (!q.empty()) {
        int sz = q.size();
        vector<int> level;
        for (int i = 0; i < sz; i++) {
            TreeNode* n = q.front(); q.pop();
            level.push_back(n->val);
            if (n->left) q.push(n->left);
            if (n->right) q.push(n->right);
        }
        res.push_back(level);
    }
    return res;
}

int diameter(TreeNode* root, int& best) {
    if (!root) return 0;
    int l = diameter(root->left, best);
    int r = diameter(root->right, best);
    best = max(best, l + r);      // path through this node
    return 1 + max(l, r);         // height upward
}

static class TreeNode { int val; TreeNode left, right; TreeNode(int v) { val = v; } }

// Inorder, recursive.
static void inorder(TreeNode r, List<Integer> out) {
    if (r == null) return;
    inorder(r.left, out); out.add(r.val); inorder(r.right, out);
}

// Inorder, iterative — worth knowing; interviewers ask for it.
static List<Integer> inorderIter(TreeNode root) {
    List<Integer> out = new ArrayList<>();
    Deque<TreeNode> st = new ArrayDeque<>();
    TreeNode cur = root;
    while (cur != null || !st.isEmpty()) {
        while (cur != null) { st.push(cur); cur = cur.left; }
        cur = st.pop();
        out.add(cur.val);
        cur = cur.right;
    }
    return out;
}

// Level order (BFS) — the basis of every "views" problem.
Queue<TreeNode> q = new ArrayDeque<>();
if (root != null) q.offer(root);
while (!q.isEmpty()) {
    int size = q.size();                 // fix the level boundary first
    for (int i = 0; i < size; i++) {
        TreeNode n = q.poll();
        if (n.left != null) q.offer(n.left);
        if (n.right != null) q.offer(n.right);
    }
}

class TreeNode:
    def __init__(self, val: int = 0, left=None, right=None):
        self.val, self.left, self.right = val, left, right

def inorder(root: TreeNode | None) -> list[int]:
    if not root:
        return []
    return inorder(root.left) + [root.val] + inorder(root.right)

# Iterative inorder — asked for explicitly in interviews.
def inorder_iter(root: TreeNode | None) -> list[int]:
    out, stack, cur = [], [], root
    while cur or stack:
        while cur:
            stack.append(cur)
            cur = cur.left
        cur = stack.pop()
        out.append(cur.val)
        cur = cur.right
    return out

# Level order (BFS) — fix the level size before the inner loop, or you will
# consume nodes belonging to the next level.
from collections import deque

def level_order(root: TreeNode | None) -> list[list[int]]:
    if not root:
        return []
    out, q = [], deque([root])
    while q:
        level = []
        for _ in range(len(q)):
            n = q.popleft()
            level.append(n.val)
            if n.left:  q.append(n.left)
            if n.right: q.append(n.right)
        out.append(level)
    return out

#include <stdlib.h>

typedef struct TreeNode {
    int val;
    struct TreeNode *left, *right;
} TreeNode;

void inorder(TreeNode *r, int *out, int *k) {
    if (!r) return;
    inorder(r->left, out, k);
    out[(*k)++] = r->val;
    inorder(r->right, out, k);
}

/* Iterative inorder with an explicit stack — the same shape the recursive
   version builds implicitly. */
void inorderIter(TreeNode *root, int *out, int *k) {
    TreeNode **st = malloc(1024 * sizeof *st);
    int top = -1;
    TreeNode *cur = root;
    while (cur || top >= 0) {
        while (cur) { st[++top] = cur; cur = cur->left; }
        cur = st[top--];
        out[(*k)++] = cur->val;
        cur = cur->right;
    }
    free(st);
}

int maxDepth(TreeNode *r) {
    if (!r) return 0;
    int l = maxDepth(r->left), rr = maxDepth(r->right);
    return 1 + (l > rr ? l : rr);
}

/* Post-order is the only safe order in which to free a tree: you must not
   touch a node's children after freeing the node. */
void tree_free(TreeNode *r) {
    if (!r) return;
    tree_free(r->left);
    tree_free(r->right);
    free(r);
}

type TreeNode struct {
	Val         int
	Left, Right *TreeNode
}

func inorder(root *TreeNode, out *[]int) {
	if root == nil {
		return
	}
	inorder(root.Left, out)
	*out = append(*out, root.Val)
	inorder(root.Right, out)
}

// Iterative inorder — interviewers ask for this explicitly.
func inorderIter(root *TreeNode) []int {
	var out []int
	var stack []*TreeNode
	cur := root
	for cur != nil || len(stack) > 0 {
		for cur != nil {
			stack = append(stack, cur)
			cur = cur.Left
		}
		cur = stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		out = append(out, cur.Val)
		cur = cur.Right
	}
	return out
}

// Level order (BFS). Capture the level size BEFORE the inner loop or you
// consume nodes from the next level.
func levelOrder(root *TreeNode) [][]int {
	if root == nil {
		return nil
	}
	var out [][]int
	q := []*TreeNode{root}
	for len(q) > 0 {
		n := len(q)
		level := make([]int, 0, n)
		for i := 0; i < n; i++ {
			node := q[0]
			q = q[1:]
			level = append(level, node.Val)
			if node.Left != nil {
				q = append(q, node.Left)
			}
			if node.Right != nil {
				q = append(q, node.Right)
			}
		}
		out = append(out, level)
	}
	return out
}

