// hold against inherited bounds, not just the immediate parent. Checking
// only the parent is the classic wrong answer.
static boolean isValid(TreeNode r, Long lo, Long hi) {
    if (r == null) return true;
    if (lo != null && r.val <= lo) return false;
    if (hi != null && r.val >= hi) return false;
    return isValid(r.left, lo, (long) r.val) && isValid(r.right, (long) r.val, hi);
}

