/* No priority_queue in C — but a heap IS just an array with index
   arithmetic: children of i are 2i+1 and 2i+2, parent is (i-1)/2. */
typedef struct { int *a; int n, cap; } Heap;

static void swap(int *x, int *y) { int t = *x; *x = *y; *y = t; }

/* Sift up after inserting at the end. */
void heap_push(Heap *h, int x) {
    int i = h->n++;
    h->a[i] = x;
    while (i > 0) {
        int p = (i - 1) / 2;
        if (h->a[p] <= h->a[i]) break;   /* min-heap: parent must be smaller */
        swap(&h->a[p], &h->a[i]);
        i = p;
    }
}

/* Move the last element to the root, then sift down. */
int heap_pop(Heap *h) {
    int top = h->a[0];
    h->a[0] = h->a[--h->n];
    int i = 0;
    for (;;) {
        int l = 2 * i + 1, r = l + 1, m = i;
        if (l < h->n && h->a[l] < h->a[m]) m = l;
        if (r < h->n && h->a[r] < h->a[m]) m = r;
        if (m == i) break;
        swap(&h->a[i], &h->a[m]);
        i = m;
    }
    return top;
}

/* Kth largest: keep a min-heap of size k, evicting the smallest. O(n log k). */

// Go has no ready-made priority queue: container/heap gives you the algorithms
// and you supply the storage by implementing heap.Interface.
type IntHeap []int

func (h IntHeap) Len() int            { return len(h) }
func (h IntHeap) Less(i, j int) bool  { return h[i] < h[j] } // min-heap; flip for max
func (h IntHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *IntHeap) Push(x any)         { *h = append(*h, x.(int)) }
func (h *IntHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

// Note Push/Pop are the storage hooks — you call heap.Push/heap.Pop, never
// these directly, or the heap invariant is not maintained.
func kthLargest(nums []int, k int) int {
	h := &IntHeap{}
	heap.Init(h)
	for _, x := range nums {
		heap.Push(h, x)
		if h.Len() > k {
			heap.Pop(h) // evict the smallest
		}
	}
	return (*h)[0]
}

vector<int> twoSum(vector<int>& nums, int target) {
    unordered_map<int,int> seen;   // value -> index
    for (int i = 0; i < (int)nums.size(); i++) {
        int need = target - nums[i];
        if (seen.count(need)) return {seen[need], i};
        seen[nums[i]] = i;
