int subarraySum(vector<int>& nums, int k) {
    unordered_map<int,int> cnt{{0,1}};
    int sum = 0, res = 0;
    for (int x : nums) {
        sum += x;
        res += cnt[sum - k];   // seen a prefix that completes k
        cnt[sum]++;
    }
    return res;
}

// Two Sum: store what you've seen, look for the complement. One pass, O(n).
static int[] twoSum(int[] nums, int target) {
    Map<Integer, Integer> seen = new HashMap<>();   // value -> index
    for (int i = 0; i < nums.length; i++) {
        Integer j = seen.get(target - nums[i]);
        if (j != null) return new int[]{j, i};
        seen.put(nums[i], i);
    }
    return new int[]{-1, -1};
}

// Subarray sum equals K: count prefix sums seen so far.
// The seed count.put(0, 1) accounts for a prefix that is itself the answer.
static int subarraySum(int[] nums, int k) {
    Map<Integer, Integer> count = new HashMap<>();
    count.put(0, 1);
    int sum = 0, res = 0;
    for (int n : nums) {
        sum += n;
        res += count.getOrDefault(sum - k, 0);
        count.merge(sum, 1, Integer::sum);
    }
    return res;
}

