/* No unordered_map. For interview-sized input, a fixed-capacity open-address
   table is enough and easy to reason about. Keep the load factor under ~0.7
   or linear probing degrades badly. */
#define CAP 2053                    /* prime */

typedef struct { int key, val; char used; } Slot;
static Slot table[CAP];

static unsigned hash(int k) {
    unsigned x = (unsigned) k;
    x = ((x >> 16) ^ x) * 0x45d9f3b; /* cheap integer mix — sequential keys
                                        otherwise cluster badly */
    x = ((x >> 16) ^ x) * 0x45d9f3b;
    return (x >> 16) ^ x;
}

int *map_get(int key) {
    unsigned h = hash(key) % CAP;
    while (table[h].used) {
        if (table[h].key == key) return &table[h].val;
        h = (h + 1) % CAP;           /* linear probe */
    }
    return NULL;
}

void map_put(int key, int val) {
    unsigned h = hash(key) % CAP;
    while (table[h].used && table[h].key != key) h = (h + 1) % CAP;
    table[h].key = key; table[h].val = val; table[h].used = 1;
}

/* Two Sum with it: store seen values, look for the complement. */
int twoSum(const int *nums, int n, int target, int *out) {
    memset(table, 0, sizeof table);
    for (int i = 0; i < n; i++) {
        int *j = map_get(target - nums[i]);
        if (j) { out[0] = *j; out[1] = i; return 1; }
        map_put(nums[i], i);
    }
    return 0;
}

// Two Sum: store what you've seen, look for the complement. One pass, O(n).
func twoSum(nums []int, target int) []int {
	seen := make(map[int]int, len(nums)) // value -> index
	for i, x := range nums {
		if j, ok := seen[target-x]; ok {
			return []int{j, i}
		}
		seen[x] = i
	}
	return nil
}

// Subarray sum equals K. The count[0] = 1 seed accounts for a prefix that is
// itself the answer; without it you miss every subarray starting at index 0.
func subarraySum(nums []int, k int) int {
	count := map[int]int{0: 1}
	sum, res := 0, 0
	for _, x := range nums {
		sum += x
		res += count[sum-k] // absent key yields 0 — convenient here
		count[sum]++
	}
	return res
}

