typedef struct { int start, end; } Interval;

/* Activity selection: sort by END time. Sorting by start or by duration both
   fail; finishing earliest leaves the most room for what follows. */
static int cmp_end(const void *p, const void *q) {
    int a = ((const Interval *) p)->end, b = ((const Interval *) q)->end;
    return (a > b) - (a < b);       /* not a - b: that can overflow */
}

int maxNonOverlapping(Interval *iv, int n) {
    qsort(iv, (size_t) n, sizeof *iv, cmp_end);
    int count = 0, lastEnd = INT_MIN;
    for (int i = 0; i < n; i++) {
        if (iv[i].start >= lastEnd) { count++; lastEnd = iv[i].end; }
    }
    return count;
}

/* Jump game: track the furthest reachable index. */
int canJump(const int *nums, int n) {
    int reach = 0;
    for (int i = 0; i < n; i++) {
        if (i > reach) return 0;
        if (i + nums[i] > reach) reach = i + nums[i];
    }
    return 1;
}

// Activity selection: sort by END time. Sorting by start or by duration both
// fail; finishing earliest leaves the most room for everything after.
func maxNonOverlapping(intervals [][]int) int {
	slices.SortFunc(intervals, func(a, b []int) int { return a[1] - b[1] })
	count, lastEnd := 0, math.MinInt
	for _, iv := range intervals {
		if iv[0] >= lastEnd {
			count++
			lastEnd = iv[1]
		}
	}
	return count
}

// Merge intervals: sort by START, then extend or append.
func merge(intervals [][]int) [][]int {
	slices.SortFunc(intervals, func(a, b []int) int { return a[0] - b[0] })
	var out [][]int
	for _, iv := range intervals {
		if n := len(out); n > 0 && iv[0] <= out[n-1][1] {
			out[n-1][1] = max(out[n-1][1], iv[1])
		} else {
			out = append(out, []int{iv[0], iv[1]})
		}
	}
	return out
}

